#!/usr/bin/env python3
# Tig-compatible text-mode interface for Git, reimplemented from observed behaviour.
import os
import sys
import re
import shlex
import subprocess
import time
import datetime
import unicodedata
import locale
import signal
from dataclasses import dataclass, field

VERSION = "2.6.0-g6d1ab9a"
VERSION_LINE = "tig version 2.6.0-g6d1ab9a\nncursesw version 6.3.20211021\n"
HELP_TEXT = """tig 2.6.0-g6d1ab9a \n\nUsage: tig        [options] [revs] [--] [paths]\n   or: tig log    [options] [revs] [--] [paths]\n   or: tig show   [options] [revs] [--] [paths]\n   or: tig reflog [options] [revs]\n   or: tig blame  [options] [rev] [--] path\n   or: tig grep   [options] [pattern]\n   or: tig refs   [options]\n   or: tig stash  [options]\n   or: tig status\n   or: tig <      [git command output]\n\nOptions:\n  +<number>       Select line <number> in the first view\n  -v, --version   Show version and exit\n  -h, --help      Show help message and exit\n  -C <path>       Start in <path>\n"""

def die(msg):
    # msg without trailing newline
    try:
        sys.stderr.write("tig: %s\n" % msg)
        sys.stderr.flush()
    except Exception:
        pass
    raise SystemExit(1)

def warn_msg(msg):
    try:
        sys.stderr.write("tig warning: %s\n" % msg)
        sys.stderr.flush()
    except Exception:
        pass

# ---------- wide-char helpers ----------
def char_width(ch):
    if not ch:
        return 0
    if isinstance(ch, tuple):  # glyph
        return 1
    if ch == '\t':
        return 8
    o = ord(ch)
    if o == 0:
        return 0
    if o < 32 or (0x7f <= o < 0xa0):
        return 0
    if unicodedata.combining(ch):
        return 0
    if unicodedata.east_asian_width(ch) in ('W', 'F'):
        return 2
    return 1

def str_width(s):
    return sum(char_width(c) for c in s)

def expand_tabs(s, tab_size=8, start_col=0):
    if '\t' not in s:
        return s
    out=[]
    col=start_col
    for c in s:
        if c=='\t':
            n = tab_size - (col % tab_size) if tab_size else 0
            out.append(' '*n); col += n
        else:
            out.append(c); col += char_width(c)
    return ''.join(out)

# Glyphs are represented in rendered cell streams as tuples ('glyph', key)
# key -> (ascii, acs_letter, utf8)
GLYPHS = {
    'vline': ('|', 'x', '│'),
    'hline': ('-', 'q', '─'),
    'urcorner': ('.', 'k', '╮'),
    'lrcorner': ("'", 'j', '╯'),
    'llcorner': (',', 'm', '╰'),  # placeholder refined for graph
    'ulcorner': ('.', 'l', '╭'),
    'ttee': ('-', 'w', '┬'),
    'btee': ('-', 'v', '┴'),
    'ltee': ('|', 't', '├'),
    'rtee': ('|', 'u', '┤'),
    'plus': ('+', 'n', '┼'),
    'commit': ('*', 'o', '∙'),
    'commit-initial': ('I', 'I', '◎'),
    'commit-merge': ('M', 'M', '●'),
    'commit-uncommitted': ('o', 'o', 'o'),
    'commit-boundary': ('-', '-', '-'),
    'sbs': ('\\', 'e', '╲'),  # not used yet
}
def glyph(key):
    return ('glyph', key)

def is_glyph(c):
    return isinstance(c, tuple) and len(c)==2 and c[0]=='glyph'

