# ---------- Keys ----------
SPECIAL_KEY_ALIASES = {
 'enter':'Enter','space':'Space','backspace':'Backspace','tab':'Tab','escape':'Escape','esc':'Escape',
 'left':'Left','right':'Right','up':'Up','down':'Down','insert':'Insert','ins':'Insert','delete':'Delete','del':'Delete',
 'home':'Home','end':'End','pageup':'PageUp','pgup':'PageUp','pagedown':'PageDown','pgdown':'PageDown',
 'scrollback':'ScrollBack','sback':'ScrollBack','scrollfwd':'ScrollFwd','sfwd':'ScrollFwd',
 'shifttab':'ShiftTab','backtab':'ShiftTab','shiftleft':'ShiftLeft','shiftright':'ShiftRight','shiftdelete':'ShiftDelete','shiftdel':'ShiftDelete','shifthome':'ShiftHome','shiftend':'ShiftEnd',
}
def char_token(c): return ('char', c)
def key_token(name): return ('key', name)
def ctrl_token(ch): return ('ctrl', ch.upper() if isinstance(ch,str) else ch)
def esc_token(inner): return ('esc', inner)

def parse_one_key_name(name):
    """Inside <...>; return token or None"""
    low=name.lower()
    if low in SPECIAL_KEY_ALIASES: return key_token(SPECIAL_KEY_ALIASES[low])
    if low=='hash': return char_token('#')
    if low in ('lessthan','lt'): return char_token('<')
    if low=='singlequote': return char_token("'")
    if low=='doublequote': return char_token('"')
    if re.fullmatch(r'f(1[0-9]|[1-9])', low): return key_token('F'+low[1:])
    if low.startswith('ctrl-') and len(name)>=6:
        rest=name[5:]
        if len(rest)==1: return ctrl_token(rest)
        # Ctrl-Space etc
        rl=rest.lower()
        if rl=='space': return ctrl_token('@')
        if rl in SPECIAL_KEY_ALIASES: return ('ctrlkey', SPECIAL_KEY_ALIASES[rl])
        return None
    if low.startswith('shift-'):
        rest=name[6:]
        return key_token('Shift'+rest)
    return None

def parse_key_spec(spec):
    """Config/script key token parsing. Return token or None."""
    if spec is None or spec=='':
        return None
    # <Esc>key combination
    if spec.lower().startswith('<esc>') and len(spec)>5:
        inner=parse_key_spec(spec[5:])
        return esc_token(inner) if inner else None
    if spec.lower().startswith('<escape>') and len(spec)>8:
        inner=parse_key_spec(spec[9:] if spec.lower().startswith('<escape>') else spec[8:])
        return esc_token(inner) if inner else None
    if len(spec)>=3 and spec.startswith('<') and spec.endswith('>'):
        return parse_one_key_name(spec[1:-1])
    if spec.startswith('<'):
        # maybe <Ctrl-C> plus trailing? not in config
        end=spec.find('>')
        if end>0 and end==len(spec)-1:
            return parse_one_key_name(spec[1:end])
        return None
    if len(spec)==1:
        return char_token(spec)
    # Some symbolic names without brackets are not valid in tigrc
    return None

def token_save_name(tok):
    if tok is None: return ''
    kind=tok[0]
    if kind=='char':
        c=tok[1]
        if c=='#': return '<Hash>'
        if c=='<': return '<LessThan>'
        if c==' ': return '<Space>'
        if c=="'": return '<SingleQuote>'
        if c=='"': return '<DoubleQuote>'
        return c
    if kind=='key': return f"<{tok[1]}>"
    if kind=='ctrl': return f"<Ctrl-{tok[1]}>"
    if kind=='ctrlkey': return f"<Ctrl-{tok[1]}>"
    if kind=='esc': return '<Esc>'+token_save_name(tok[1])
    return f"<{tok[1]}>"

def token_help_name(tok):
    if tok is None: return ''
    if tok[0]=='char':
        c=tok[1]
        if c==' ': return '<Space>'
        return c
    return token_save_name(tok)

def parse_key_sequence(s):
    """Parse script line into tokens. Each char is a token; <...> composite."""
    toks=[]; i=0
    while i<len(s):
        if s[i]=='<':
            end=s.find('>',i)
            if end!=-1:
                name=s[i+1:end]
                if name.lower() in ('esc','escape') and end+1<len(s):
                    # <Esc>x as one combined token: consume next char/spec
                    if s[end+1]=='<':
