KNOWN_COLOR_NAMES = {'black','red','green','yellow','blue','magenta','cyan','white','default'}
KNOWN_ATTRS = {'normal','blink','bold','dim','reverse','standout','underline'}
BUILTIN_COLOR_AREAS = set('''default cursor cursor-blur status delimiter date mode id overflow directory file grep.file grep.line-number grep.delimiter file-size line-number title-blur title-focus header section main-commit main-annotated main-tag main-local-tag main-remote main-stash main-note main-prefetch main-other main-replace main-tracked main-ref main-head stat-none stat-staged stat-unstaged stat-untracked help-group help-action help-toggle diff-stat diff-header diff-chunk diff-add diff-add2 diff-del diff-del2 diff-add-highlight diff-del-highlight diff-index diff-oldmode diff-newmode diff-newfmode diff-delfmode diff-copy-from diff-copy-to diff-similarity diff-del-file diff-add-file diff-start graph-commit search-result pp-refs pp-reflog pp-reflogmsg pp-merge commit parent tree author committer tree-dir tree-file status.header'''.split())
for _i in range(14): BUILTIN_COLOR_AREAS.add(f'palette-{_i}')

def canonical_area(name):
    return name.strip().lower().replace('_','-')

def strip_comment(line):
    out=[]; in_s=False; in_d=False; esc=False
    for c in line:
        if esc:
            out.append(c); esc=False; continue
        if c=='\\':
            out.append(c);
            # backslash inside quotes only special partially; keep simple
            continue
        if in_s:
            out.append(c)
            if c=="'": in_s=False
            continue
        if in_d:
            out.append(c)
            if c=='"': in_d=False
            continue
        if c=="'": in_s=True; out.append(c); continue
        if c=='"': in_d=True; out.append(c); continue
        if c=='#': break
        out.append(c)
    return ''.join(out)

def split_config_tokens(s, keep_quotes=False):
    """Whitespace tokeniser respecting single/double quotes. Returns tokens without outer quotes for quoted segments merged."""
    toks=[]; cur=[]; in_s=False; in_d=False; has=False
    i=0
    while i<len(s):
        c=s[i]
        if in_s:
            if c=="'": in_s=False
            else: cur.append(c)
            i+=1; continue
        if in_d:
            if c=='"': in_d=False
            else: cur.append(c)
            i+=1; continue
        if c=="'": in_s=True; has=True; i+=1; continue
        if c=='"': in_d=True; has=True; i+=1; continue
        if c.isspace():
