            continue
        if in_d:
            cur.append(c)
            if c=='"': in_d=False
            continue
        if c=="'": in_s=True; cur.append(c); continue
        if c=='"': in_d=True; cur.append(c); continue
        if c==',':
            parts.append(''.join(cur)); cur=[]; continue
        cur.append(c)
    if cur: parts.append(''.join(cur))
    return parts

