        self.options={}   # name->value (view -> list[Column], bool->'yes'/'no', int->int, string->str)
        self.bindings=[]  # list[Binding]
        self.colors={}    # key -> ColorEntry; key ('name',canon) or ('str',string)
        self.color_order=[]
        self.errors=0
        self.trace_file=None
        # defaults before builtin lines so format_view etc can work
        self.init_option_placeholders()
    def init_option_placeholders(self):
        for name,(kind,kw) in OPTION_DEFS.items():
            if kind=='view':
                self.options[name]=[]
            elif kind=='bool': self.options[name]='no'
            elif kind=='int': self.options[name]=0
            elif kind=='args': self.options[name]=[]
            else: self.options[name]=''
    def get(self,name,default=None):
        return self.options.get(name,default)
    def get_bool(self,name):
        v=self.options.get(name,'no')
        return v=='yes' if isinstance(v,str) else bool(v)
    def get_int(self,name,default=0):
        try: return int(self.options.get(name,default))
        except Exception: return default

    # ---- bindings ----
    def infer_group(self, keymap, action):
        if action.startswith(':toggle'): return 'Option toggling:'
        if action.startswith(':'): return 'Internal commands:'
        if action and action[0] in '!?@<+>': return 'External commands:'
        info=ACTION_INFO.get(action)
        return info[0] if info else 'Misc'
    def set_binding(self, keymap, token, action, group=None):
        if group is None: group=self.infer_group(keymap,action)
        # action none clears
        if action=='none':
            self.bindings=[b for b in self.bindings if not (b.keymap==keymap and b.token==token)]
            # Docs: bind generic key none clears in all maps? Statement: Clear from all keymaps at once with bind generic key none
            if keymap=='generic':
                self.bindings=[b for b in self.bindings if b.token!=token]
            return
        for b in self.bindings:
            if b.keymap==keymap and b.token==token:
                b.action=action; b.group=group; return
        self.bindings.append(Binding(keymap,token,action,group))
    def lookup_binding(self, viewname, token):
        # view specific first, then generic
        for b in reversed(self.bindings):
            if b.keymap==viewname and b.token==token: return b.action
        for b in reversed(self.bindings):
            if b.keymap=='generic' and b.token==token: return b.action
        return None
    # ---- colors ----
    def set_color(self, area_display, is_string, fg, bg, attrs):
        if is_string:
            key=('str', area_display)
            disp=area_display
        else:
            canon=canonical_area(area_display)
            key=('name', canon)
            disp=canon
            # preserve palette numeric etc; also grep.file contains dot and hyphen normalisation may change grep-line-number? keep as supplied lower but -/_ canonical for lookup only
            # For save display use original default spellings: canonical form is close (lowercase, -)
            # Special: grep.line-number from git-colors not a direct color entry
        if key not in self.colors:
            self.colors[key]=ColorEntry(disp,is_string,fg,bg,list(attrs))
            self.color_order.append(key)
        else:
            e=self.colors[key]; e.fg=fg; e.bg=bg; e.attrs=list(attrs)
    def get_color_entry(self, area, viewname=None):
        # view specific first
        if viewname:
            key=('name', canonical_area(f"{viewname}.{area}"))
            if key in self.colors: return self.colors[key]
        key=('name', canonical_area(area))
        if key in self.colors: return self.colors[key]
        # line-type prefix mapping fallback resolved by caller
        return None

