REF_TYPE_ORDER = ['head','branch','tracked-remote','remote','tag','local-tag','replace','stash','note','prefetch','other']
def default_ref_formats():
    return {'branch':('[',']',False),'remote':('{','}',False),'tag':('<','>',False),'replace':('~','~',False)}

def format_reference_formats(fmts):
    out=[]
    for t in REF_TYPE_ORDER:
        if t in fmts:
            pre,suf,hide=fmts[t]
            if hide: out.append(f"hide:{t}")
            else: out.append(f"{pre}{t}{suf}")
    return ' '.join(out)

# Patch set_option handling for reference-format
_orig_set_option = Config.set_option
def _config_set_option2(self, name_raw, value):
    name=name_raw.lower().replace('_','-')
    if name=='reference-format':
        fmts=getattr(self,'ref_formats',None)
        if fmts is None: fmts=default_ref_formats(); self.ref_formats=fmts
        toks=split_config_tokens(str(value))
        for tok in toks:
            if tok.startswith('hide:'):
                t=tok[5:]
                if t in REF_TYPE_ORDER:
                    pre,suf,_=fmts.get(t,('[',']',False)); fmts[t]=(pre,suf,True)
                continue
            # find type name inside token
            matched=None
            for t in sorted(REF_TYPE_ORDER,key=len,reverse=True):
                if t in tok: matched=t; break
            if matched:
                pre=tok.split(matched)[0]; suf=tok.split(matched,1)[1]
                # If it was previously hidden and a new format is set? preserve hide if token is hide handled above.
                fmts[matched]=(pre,suf,False)
        self.options['reference-format']=format_reference_formats(fmts)
        return True,None
    return _orig_set_option(self,name_raw,value)
Config.set_option=_config_set_option2
Config.ref_formats = None

# Initialise ref_formats lazily via property-like helper
def get_ref_formats(cfg):
    fmts=getattr(cfg,'ref_formats',None)
    if not fmts:
        fmts=default_ref_formats(); cfg.ref_formats=fmts
    return fmts

# ---------- Config file parsing ----------
def _config_parse_line(self, raw_line, reporter):
    line=strip_comment(raw_line).strip()
    if not line: return True
    # first word
    m=re.match(r'^(\S+)(?:\s+(.*))?$', line)
    if not m: return True
    cmd=m.group(1); rest=m.group(2) or ''
    if cmd=='set':
        # require: set name = value
        ms=re.match(r'^(\S+)\s+=\s*(.*)$', rest)
        if not ms:
            reporter("Invalid set command: set option = value"); return False
        ok,err=self.set_option(ms.group(1), ms.group(2))
        if err: reporter(err); return False
        return True
    elif cmd=='bind':
        mb=re.match(r'^(\S+)\s+(\S+)\s+(.*)$', rest)
        if not mb:
            reporter("Invalid bind command: bind keymap key action"); return False
        keymap,keys,action=mb.group(1),mb.group(2),mb.group(3).strip()
        if keymap not in KEYMAPS:
            reporter(f"Unknown key map: {keymap}"); return False
        token=parse_key_spec(keys)
        if token is None:
            # error name: strip < >
            nm=keys[1:-1] if keys.startswith('<') and keys.endswith('>') else keys
            reporter(f"Unknown key mapping: {nm}"); return False
        # validate action
        if action not in ACTION_INFO:
            if action.startswith(':') or (action and action[0] in '!?@<+>'):
                pass
            else:
                ch=action[0] if action else ''
                reporter(f"Unknown command flag '{ch}'; expected one of :!?@<>+"); return False
        self.set_binding(keymap,token,action)
        return True
    elif cmd=='color':
        mc=re.match(r'^(?:"([^"]*)"|\'([^\']*)\'|(\S+))\s+(\S+)\s+(\S+)(?:\s+(.*))?$', rest)
        if not mc:
            reporter("Invalid color command: color area fg bg [attributes]"); return False
        is_str = mc.group(1) is not None or mc.group(2) is not None
        area = mc.group(1) if mc.group(1) is not None else (mc.group(2) if mc.group(2) is not None else mc.group(3))
        fg=mc.group(4); bg=mc.group(5); attrs_s=(mc.group(6) or '').strip()
        if not is_str:
            canon=canonical_area(area)
            # view-specific prefix
            ok=False
            if canon in BUILTIN_COLOR_AREAS: ok=True
            elif '.' in canon:
                pre,sub=canon.split('.',1)
                if pre in KEYMAPS+list(VIEW_COLUMNS.keys())+['grep','status','help','tree','stage','diff'] and (sub in BUILTIN_COLOR_AREAS or canonical_area(sub) in BUILTIN_COLOR_AREAS or sub in ('date','id','author','committer','file','file-size','line-number','mode','header')): ok=True
                if canon.startswith('grep.'): ok=True
            # palette-N already in set
            if not ok:
                reporter(f"Unknown color name: {area}"); return False
        for cname in (fg,bg):
            cl=cname.lower()
            if cl in KNOWN_COLOR_NAMES or re.fullmatch(r'(color)?\d+',cl): pass
            else: reporter(f"Unknown color: {cname}"); return False
        attrs=[]
        if attrs_s:
            for a in attrs_s.split():
                if a.lower() not in KNOWN_ATTRS:
                    reporter(f"Unknown color attribute: {a}"); return False
                attrs.append(a.lower())
        self.set_color(area,is_str,fg.lower(),bg.lower(),attrs)
        return True
    elif cmd=='source':
        quiet=False; path=rest.strip()
        if path.startswith('-q '): quiet=True; path=path[3:].strip()
        elif path=='-q': path=''
        path=unquote(path)
        expanded=os.path.expanduser(path)
        if not os.path.exists(expanded):
            if not quiet: reporter(f"File does not exist: {path}"); return False
            return True
        return self.load_file(expanded)
    else:
        reporter(f"Unknown option command: {cmd}"); return False

def _config_load_file(self, path, reporter=None):
    # reporter: callable(msg, path, lineno) or None -> warnings to stderr
    try:
        with open(path,'r',encoding='utf-8',errors='surrogateescape') as f:
            physical=f.readlines()
    except Exception:
        return False
    errors=0
    i=0
    while i<len(physical):
        start=i+1
        line=physical[i].rstrip('\n')
        while line.endswith('\\') and i+1<len(physical):
            line=line[:-1]+physical[i+1].rstrip('\n'); i+=1
        def rep(msg, _p=path,_l=start):
            nonlocal errors
            errors+=1
            if reporter: reporter(msg,_p,_l)
            else: warn_msg(f"{_p}:{_l}: {msg}")
        self.parse_line(line, rep)
        i+=1
    if errors:
        if reporter: reporter(f"Errors while loading {path}.",path,0)
        else: warn_msg(f"Errors while loading {path}.")
    return errors==0

def _config_load_defaults(self):
    self.ref_formats=default_ref_formats()
    def nop(msg): pass
    for line in DEFAULT_SETTING_LINES:
        self.parse_line(line,nop)
    for group,line in DEFAULT_BINDINGS:
        ok_line=line
        # parse manually to preserve group
        mb=re.match(r'^bind\s+(\S+)\s+(\S+)\s+(.*)$', ok_line)
        if mb:
            keymap,keys,action=mb.groups()
            token=parse_key_spec(keys)
            if token: self.set_binding(keymap,token,action.strip(),group=group)
    for line in DEFAULT_COLOR_LINES:
        self.parse_line(line,nop)

Config.parse_line=_config_parse_line
Config.load_file=_config_load_file
Config.load_defaults=_config_load_defaults

# ---------- Save options ----------
def format_option_value(cfg,name):
    v=cfg.options.get(name,'')
    kind=OPTION_DEFS[name][0]
    if kind=='view': return format_view_columns(v)
    if kind=='bool': return v if isinstance(v,str) else bool_to_yesno(v)
    if kind=='int': return str(v)
    if name=='diff-highlight':
        return f'"{v}"'
    if name=='truncation-delimiter':
        return f'"{v}"'
    if name=='reference-format':
        return format_reference_formats(get_ref_formats(cfg))
    return str(v)

def save_options_text(cfg):
    lines=[]
    lines.append("# Saved by Tig")
    lines.append("")
    lines.append("## Settings")
    lines.append("")
    for name in SAVE_OPTION_ORDER:
        lines.append(f"set {name:<25} = {format_option_value(cfg,name)}")
    lines.append("")
    lines.append("## Keybindings")
    lines.append("")
    prev_group=None
    for b in cfg.bindings:
        if b.group!=prev_group:
            lines.append(f"# {b.group}")
            prev_group=b.group
        lines.append(f"bind {b.keymap:<10} {token_save_name(b.token):<15} {b.action}")
    lines.append("")
    lines.append("## Colors")
    lines.append("")
    color_lines=[]
    for key in cfg.color_order:
        e=cfg.colors[key]
        if e.is_string:
            disp=f'"{e.area}"'
        else:
            disp=e.area
        base=f"color {disp:<30} {e.fg:<8} {e.bg:<8}"
        if e.attrs:
            base += " " + " ".join(e.attrs)
        color_lines.append(base)
    lines.extend(color_lines)
    # last line without trailing newline to match original
    return "\n".join(lines)

