# ---------- Git runner / trace ----------
class GitRunner:
    def __init__(self):
        self.trace_path=os.environ.get('TIG_TRACE') or None
        self._trace_fh=None
    def trace_handle(self):
        if not self.trace_path: return None
        if self._trace_fh is None:
            try: self._trace_fh=open(self.trace_path,'ab')
            except Exception: self._trace_fh=None
        return self._trace_fh
    def trace(self, argv):
        fh=self.trace_handle()
        if fh is not None:
            try:
                fh.write((' '.join(str(a) for a in argv)+' \n').encode('utf-8','surrogateescape')); fh.flush()
            except Exception: pass
    def run(self, argv, input_data=None, merge_stderr=False, cwd=None):
        self.trace(argv)
        fh=self.trace_handle()
        try:
            p=subprocess.run(argv, input=input_data, stdout=subprocess.PIPE, stderr=(subprocess.STDOUT if merge_stderr else (fh if fh is not None else subprocess.DEVNULL)), cwd=cwd)
            return p.returncode, p.stdout or b''
        except FileNotFoundError as e:
            return 127, b''
        except Exception:
            return 1,b''
    def run_shell(self, command, input_data=None, merge_stderr=False):
        # Split shell-like; if it needs shell metachars fall back to sh -c and trace words from shlex for simple case
        try: argv=shlex.split(command)
        except Exception: argv=[]
        if argv and not any(c in command for c in '|&;<>$`'):
            # strip possible globs quoting already handled; execution without glob expansion differs only when pattern includes * - git handles it
            return self.run(argv,input_data=input_data,merge_stderr=merge_stderr)
        self.trace(argv if argv else [command])
        fh=self.trace_handle()
        p=subprocess.run(command,shell=True,input=input_data,stdout=subprocess.PIPE,stderr=(subprocess.STDOUT if merge_stderr else (fh if fh is not None else subprocess.DEVNULL)))
        return p.returncode,p.stdout or b''

def decode(b):
    return b.decode('utf-8','surrogateescape') if isinstance(b,bytes) else b

