def format_relative_date(ts, compact=False, now_ts=None):
    if now_ts is None: now_ts=int(time.time())
    diff = now_ts - int(ts)
    ahead = diff < 0
    adiff = abs(diff)
    # thresholds observed
    if adiff < 120:
        val=adiff; unit='second'; cunit='s'
    elif adiff < 7200:
        val=adiff//60; unit='minute'; cunit='m'
    elif adiff < 172800:
        val=adiff//3600; unit='hour'; cunit='h'
    elif adiff < 1209600:
        val=adiff//86400; unit='day'; cunit='D'
    elif adiff < 7776000:
        val=adiff//604800; unit='week'; cunit='W'
    elif adiff < 31536000:
        val=adiff//2592000; unit='month'; cunit='M'
    else:
        val=adiff//31536000; unit='year'; cunit='Y'
    if compact:
        return f"-{val}{cunit}" if ahead else f"{val}{cunit}"
    plural='s' if val>1 else ''
    return f"{val} {unit}{plural} ahead" if ahead else f"{val} {unit}{plural} ago"

