def parse_main_log_output(data_bytes):
    text=decode(data_bytes)
    commits=[]
    records=text.split('\x03')
    for rec in records:
        rec=rec.lstrip('\n') if False else rec
        if rec.startswith('\n'): rec=rec[1:]
        if not rec.strip(): continue
        parts=rec.split('\x00')
        if len(parts)<4: continue
        header,auth,comm,rest = parts[0],parts[1],parts[2],parts[3:]
        title=rest[0] if rest else ''
        notes=rest[1] if len(rest)>1 else ''
        # header: commit <marker> <id> [<parents>]
        toks=header.split()
        if len(toks)<3 or toks[0]!='commit': continue
        marker=toks[1]; cid=toks[2]; parents=toks[3:]
        an,ae,ad=parse_person(auth); cn,ce,cd=parse_person(comm)
        commits.append(CommitInfo(id=cid,parents=parents,author_name=an,author_email=ae,author_date=ad,committer_name=cn,committer_email=ce,committer_date=cd,title=title.rstrip('\n'),notes=notes,marker=marker))
    return commits

def parse_raw_commits(text):
    commits=[]; cur=None; in_msg=False
    for line in text.splitlines():
        if line.startswith('commit ') and (cur is None or in_msg or True):
            # new commit if line at top level (commit lines in msg are indented)
            cid=line[7:].strip().split()[0] if line[7:].strip() else ''
            cur=CommitInfo(id=cid); commits.append(cur); in_msg=False; continue
        if cur is None: continue
        if not in_msg:
            if line=='': in_msg=True; continue
            if line.startswith('tree '): cur.tree=line[5:].strip()
            elif line.startswith('parent '): cur.parents.append(line[7:].strip())
            elif line.startswith('author '):
                n,e,d=parse_person(line[7:]); cur.author_name=n; cur.author_email=e; cur.author_date=d
            elif line.startswith('committer '):
                n,e,d=parse_person(line[10:]); cur.committer_name=n; cur.committer_email=e; cur.committer_date=d
            elif line.startswith('Reflog: '):
                sel=line[8:].strip().split(' ')[0]; cur.reflog_selector=sel
            elif line.startswith('Reflog message: '):
                cur.reflog_message=line[16:].strip()
            continue
        else:
            # message lines indented 4 spaces; first non-empty is title if not set
            msg=line[4:] if line.startswith('    ') else line
            if not cur.title and msg.strip():
                cur.title=msg
    for c in commits:
        if c.author_date is None: c.author_date=DateInfo()
        if c.committer_date is None: c.committer_date=DateInfo()
    return commits

