@dataclass
class DateInfo:
    ts:int=0
    tz:str='+0000'
    def tzinfo(self):
        m=re.match(r'^([+-])(\d\d)(\d\d)$',self.tz or '+0000')
        if not m: return datetime.timezone.utc
        sign=1 if m.group(1)=='+' else -1
        return datetime.timezone(sign*datetime.timedelta(hours=int(m.group(2)),minutes=int(m.group(3))))
    def dt_source(self):
        return datetime.datetime.fromtimestamp(self.ts, tz=self.tzinfo())
    def dt_local(self):
        return datetime.datetime.fromtimestamp(self.ts).astimezone()

def format_date(dinfo, colopts, now_ts=None):
    if dinfo is None: return ''
    display=colopts.get('display','default') if colopts else 'default'
    if display=='no': return ''
    local = colopts.get('local','no')=='yes' if colopts else False
    if display in ('relative','relative-compact'):
        return format_relative_date(dinfo.ts, compact=(display=='relative-compact'), now_ts=now_ts)
    dt = dinfo.dt_local() if local else dinfo.dt_source()
    if display=='custom':
        fmt=colopts.get('format','') if colopts else ''
        if not fmt: return ''
        try: return dt.strftime(fmt)
        except Exception: return ''
