def parse_person(seg):
    """'Name <email> ts tz' -> (name,email,DateInfo)"""
    if seg is None: return ('','',DateInfo())
    m=re.match(r'^(.*?) <(.*?)> (\d+) ([+-]\d{4})$', seg.strip())
    if not m:
        # name without date
        m2=re.match(r'^(.*?) <(.*?)>$', seg.strip())
        if m2: return (m2.group(1),m2.group(2),DateInfo())
        return (seg.strip(),'',DateInfo())
    return (m.group(1),m.group(2),DateInfo(int(m.group(3)),m.group(4)))

