# ---------- Graph (v2) ----------
def box_glyph(up,down,left,right):
    key=(bool(up),bool(down),bool(left),bool(right))
    m={
     (True,True,False,False):'vline',
     (False,False,True,True):'hline',
     (False,True,True,False):'urcorner',
     (False,True,False,True):'ulcorner',
     (True,False,True,False):'lrcorner',
     (True,False,False,True):'llcorner',
     (False,True,True,True):'ttee',
     (True,False,True,True):'btee',
     (True,True,True,False):'rtee',
     (True,True,False,True):'ltee',
     (True,True,True,True):'plus',
     (True,False,False,False):'vline',
     (False,True,False,False):'vline',
     (False,False,True,False):'hline',
     (False,False,False,True):'hline',
    }
    return m.get(key)

# add missing glyph entries (ascii/acs/utf8)
GLYPHS.update({
 'urcorner': ('.','k','╮'), 'ulcorner': ('.','l','╭'), 'lrcorner': ("'",'j','╯'), 'llcorner': ("'",'m','╰'),
 'ttee': ('-','w','┬'), 'btee': ('-','v','┴'), 'rtee': ('|','u','┤'), 'ltee': ('|','t','├'), 'plus': ('+','n','┼'),
 'commit-boundary': ('o','o','◯'),
})

def compute_graph(commits):
    """commits: list[CommitInfo-like with id/parents/marker]
       returns list per commit of list of (char_or_glyph, style_name) for graph cells including separators, trimmed."""
    lanes=[]  # expected id or None
    colors=[] # palette idx or None, parallel
    next_color=0
    results=[]
    def ensure(idx):
        while len(lanes)<=idx: lanes.append(None); colors.append(None)
    for commit in commits:
        before=list(lanes)
        # find expecting lanes
        expecting=[i for i,v in enumerate(before) if v==commit.id]
        is_new_tip=False
        if expecting:
            commit_lane=expecting[0]
        else:
            # first free or append
            if None in lanes: commit_lane=lanes.index(None)
            else: commit_lane=len(lanes); ensure(commit_lane)
            is_new_tip=True
            colors[commit_lane]=next_color; next_color=(next_color+1)%14
        converging=expecting[1:] if len(expecting)>1 else []
        after=list(before)
        ensure(commit_lane)
        # converging lanes freed
        for i in converging: after[i]=None
        # commit lane outgoing
        parents=list(commit.parents or [])
        # boundary commits: git may include parent but marker '-' indicates no outgoing in graph? In tig, parent is perhaps still set but commit is end of displayed history; observed row at bottom alone. If boundary and parent not in any future commits, lane continuing wouldn't matter visually as no rows after. Keep as parents.
        after[commit_lane]=parents[0] if parents else None
        fork_targets=[]
        for p in parents[1:]:
            # existing lane expecting p (from before, not commit lane)
            existing=None
            for i,v in enumerate(before):
                if v==p and i!=commit_lane:
                    existing=i; break
            if existing is not None:
                fork_targets.append(existing)
                after[existing]=p
                continue
            # allocate first free in after, or append
            if None in after:
                idx=after.index(None)
            else:
                idx=len(after); ensure(idx); after.append(None) if len(after)<=idx else None
                # ensure updated lanes length; sync after length
                while len(after)<len(lanes): after.append(None)
            ensure(idx)
            while len(after)<=idx: after.append(None)
            after[idx]=p
            colors[idx]=next_color; next_color=(next_color+1)%14
            fork_targets.append(idx)
        involved=set([commit_lane]+converging+fork_targets)
        has_h = bool(converging or fork_targets)
        hmin=min(involved) if has_h else commit_lane
        hmax=max(involved) if has_h else commit_lane
        # max lane to render
        active_idxs=[i for i,v in enumerate(before) if v is not None]+[i for i,v in enumerate(after) if v is not None]+list(involved)
        max_lane=max(active_idxs) if active_idxs else commit_lane
        cells=[]
        # node glyph
        if getattr(commit,'marker','')=='-':
            node=glyph('commit-boundary')
        elif not parents:
            node=glyph('commit-initial')
        elif len(parents)>1:
            node=glyph('commit-merge')
        else:
            # pseudo uncommitted commits identified by special marker attr
            if getattr(commit,'is_pseudo',False): node=glyph('commit')
            else: node=glyph('commit')
        for lane in range(max_lane+1):
            if lane>0:
                # separator before this lane
                sep_lane=lane-1
                if has_h and hmin<=sep_lane<hmax:
                    style=f"palette-{colors[lane] if lane < len(colors) and colors[lane] is not None else 0}"
                    cells.append((glyph('hline'),style))
                else:
                    cells.append((' ','default'))
            if lane==commit_lane:
                cells.append((node,'graph-commit'))
                continue
            up = lane < len(before) and before[lane] is not None
            down = lane < len(after) and after[lane] is not None
            if lane in involved:
                left = has_h and hmin<lane
                right= has_h and hmax>lane
                gk=box_glyph(up,down,left,right)
                if gk:
                    style=f"palette-{colors[lane] if lane < len(colors) and colors[lane] is not None else 0}"
                    cells.append((glyph(gk),style))
                else:
                    cells.append((' ','default'))
            else:
                if up and down:
                    style=f"palette-{colors[lane] if lane < len(colors) and colors[lane] is not None else 0}"
                    cells.append((glyph('vline'),style))
                elif up or down:
                    # Should be endpoint normally; draw vline
                    style=f"palette-{colors[lane] if lane < len(colors) and colors[lane] is not None else 0}"
                    cells.append((glyph('vline'),style))
                else:
                    cells.append((' ','default'))
        # trim trailing spaces
        while cells and cells[-1][0]==' ':
            cells.pop()
        results.append(cells)
        lanes=after
        while len(colors)<len(lanes): colors.append(None)
    return results

