import tig, subprocess
def commits(cwd,args=[]):
    git=tig.GitRunner(); git.trace_path=None
    rc,out=git.run(['git','log','--topo-order','--date=raw','--parents','--pretty=format:commit %m %H %P%x00%aN <%aE> %ad%x00%cN <%cE> %cd%x00%s%x00%N%x03']+args,cwd=cwd)
    return tig.parse_main_log_output(out)
def show(cwd,args=[]):
    cs=commits(cwd,args)
    gs=tig.compute_graph(cs)
    for c,g in zip(cs,gs):
        s=''.join(tig.GLYPHS[ch[1]][0] if tig.is_glyph(ch) else ch for ch,st in g)
        print(repr(s),c.title)
print("graphrepo2 --all"); show('/tmp/graphrepo2',['--all'])
print("octo --all"); show('/tmp/graphrepo',['--all'])
print("testrepo2 --all"); show('/tmp/testrepo2',['--all'])
