# ---------- App: configuration loading ----------
def _app_load_configuration(self):
    self.cfg.load_defaults()
    # system
    sys_env=os.environ.get('TIGRC_SYSTEM')
    if sys_env is not None:
        if sys_env and os.path.exists(sys_env): self.cfg.load_file(sys_env)
    else:
        if os.path.exists('/etc/tigrc'): self.cfg.load_file('/etc/tigrc')
    # user
    user_env=os.environ.get('TIGRC_USER')
    if user_env is not None:
        if user_env and os.path.exists(user_env): self.cfg.load_file(user_env)
    else:
        xdg=os.environ.get('XDG_CONFIG_HOME')
        home=os.path.expanduser('~')
        if xdg:
            p=os.path.join(xdg,'tig','config')
            if os.path.exists(p): self.cfg.load_file(p)
        else:
            p=os.path.join(home,'.config','tig','config')
            if os.path.exists(p): self.cfg.load_file(p)
            else:
                p2=os.path.join(home,'.tigrc')
                if os.path.exists(p2): self.cfg.load_file(p2)
    self.apply_git_config()

def _parse_git_color_value(v):
    toks=v.split()
    fg=None; bg=None; attrs=[]
    attrmap={'bold':'bold','dim':'dim','ul':'underline','underline':'underline','blink':'blink','reverse':'reverse','inverse':'reverse','italic':'','strike':''}
    colors={'normal':'default','-1':'default','black':'black','red':'red','green':'green','yellow':'yellow','blue':'blue','magenta':'magenta','cyan':'cyan','white':'white','default':'default'}
    for tok in toks:
        low=tok.lower()
        if low.startswith('no-') or low.startswith('no'):
            continue
        if low in attrmap:
            if attrmap[low]: attrs.append(attrmap[low])
            continue
        bright=False
        base=low
        if low.startswith('bright'):
            bright=True; base=low[6:]
        if base in colors or re.fullmatch(r'\d+',base):
            c=colors.get(base,base)
            if bright and 'bold' not in attrs: attrs.append('bold')
            if fg is None: fg=c
            elif bg is None: bg=c
            continue
        # unknown token ignore as fg
        if fg is None: fg=low
    return (fg or 'default', bg or 'default', attrs)

def _app_apply_git_config(self):
    # tig.* entries
    for key,vals in list(self.repo.git_config.items()):
        if not key.startswith('tig.'): continue
        rest=key[4:]
        for v in vals:
            def rep(msg, _k=key, _rest=rest):
                if _rest.startswith('color.'):
                    short='tig.'+_rest.split('.',1)[1] if '.' in _rest else _k
                elif _rest.startswith('bind.'):
                    short='tig.'+_rest.split('.',1)[1] if '.' in _rest else _k
                else: short=_k
                warn_msg(f"Option '{short}': {msg}")
            if rest.startswith('color.'):
                area=rest[len('color.'):]
                # area may be e.g. tree.date (keep)
                toks=v.split()
                fg=toks[0] if len(toks)>0 else 'default'; bg=toks[1] if len(toks)>1 else 'default'; attrs=toks[2:]
                line=f"color {area} {fg} {bg} {' '.join(attrs)}".rstrip()
                self.cfg.parse_line(line,rep)
            elif rest.startswith('bind.'):
                keymap=rest[len('bind.'):]
                # value: "KEY action"
                parts=v.split(None,1)
                if len(parts)==2:
                    self.cfg.parse_line(f"bind {keymap} {parts[0]} {parts[1]}",rep)
            else:
                # option name is rest (may contain dots? no)
                ok,err=self.cfg.set_option(rest,v)
                if err: rep(err)
    # git colors mapping
    if str(self.cfg.options.get('git-colors','')).lower()=='no':
        return
    pairs=[]
    for tok in str(self.cfg.options.get('git-colors','')).split():
        if '=' in tok: pairs.append(tok.split('=',1))
    if not pairs: return
    for key,vals in list(self.repo.git_config.items()):
        if not key.startswith('color.'): continue
        gkey=key[len('color.'):]
        for mk,mv in pairs:
            if mk.lower()==gkey.lower():
                for v in vals:
                    fg,bg,attrs=_parse_git_color_value(v)
                    # mv may be area name like grep.file; set directly if known else as name
                    self.cfg.set_color(mv,False,fg,bg,attrs)

App.load_configuration=_app_load_configuration
App.apply_git_config=_app_apply_git_config

# ---------- App: layout / titles ----------
def _app_layout(self):
    W=self.screen_w; H=self.screen_h
    avail_h=max(1,H-1)
    layouts=[]
    disp=self.display
    if len(disp)<=1:
        if disp:
            v=disp[0]; v.width=W; v.height=max(0,avail_h-1)
            layouts.append({'view':v,'x':0,'y':0,'w':W,'h':v.height,'title_y':avail_h-1,'title_x':0,'title_w':W})
        return layouts
    # two views: parent first, child second
    parent,child=disp[0],disp[1]
    vs=str(self.cfg.options.get('vertical-split','auto'))
    vertical=False
    if vs=='vertical': vertical=True
    elif vs=='horizontal': vertical=False
    else: vertical = W >= 4*avail_h
    if vertical:
        usable=max(0,W-1)
        spec=str(self.cfg.options.get('split-view-width','50%'))
        if spec.endswith('%'):
            try: pct=int(spec[:-1])
            except Exception: pct=50
            right_w=int(usable*pct/100)
        else:
            try: right_w=int(spec)
            except Exception: right_w=usable//2
        # ensure smaller at least 4 wide if possible
        if usable>=8:
            right_w=max(4,min(right_w,usable-4))
        left_w=usable-right_w
        h=max(0,avail_h-1)
        parent.width=left_w; parent.height=h; child.width=right_w; child.height=h
        layouts.append({'view':parent,'x':0,'y':0,'w':left_w,'h':h,'title_y':avail_h-1,'title_x':0,'title_w':left_w})
        layouts.append({'view':child,'x':left_w+1,'y':0,'w':right_w,'h':h,'title_y':avail_h-1,'title_x':left_w+1,'title_w':right_w,'sep_x':left_w})
    else:
        spec=str(self.cfg.options.get('split-view-height','67%'))
        if spec.endswith('%'):
            try: pct=int(spec[:-1])
            except Exception: pct=67
            child_total=int(avail_h*pct/100)
        else:
            try: child_total=int(spec)+1
            except Exception: child_total=avail_h*2//3
        if avail_h>=10:
            child_total=max(5,min(child_total,avail_h-5))
        parent_total=avail_h-child_total
        parent_h=max(0,parent_total-1); child_h=max(0,child_total-1)
        parent.width=W; parent.height=parent_h; child.width=W; child.height=child_h
        layouts.append({'view':parent,'x':0,'y':0,'w':W,'h':parent_h,'title_y':parent_h,'title_x':0,'title_w':W})
        layouts.append({'view':child,'x':0,'y':parent_total,'w':W,'h':child_h,'title_y':parent_total+child_h,'title_x':0,'title_w':W})
    return layouts

def _app_view_ref(self, view):
    if view.name=='finder': return ''
    line=view.selected()
    if line is not None:
        if 'view_ref' in line.data: return line.data['view_ref'] or ''
        ci=line.data.get('commitinfo')
        if ci is not None:
            return getattr(ci,'id','') or ''
        if view.name in ('diff','log','pager'):
            if view.name=='pager': return ''
            return line.data.get('commit') or view.state.get('fallback_ref','') or ''
        if view.name=='blame':
            return f"{line.data.get('commit','')}:{line.data.get('filename',view.state.get('file',''))}"
    # no selected line
    if view.name=='diff': return view.state.get('fallback_ref','') or ''
    if view.name=='blob': return view.state.get('file','') or ''
    if view.name=='stage': return view.state.get('fallback_ref','') or ''
    return view.state.get('fallback_ref','') or ''

def _app_title_text(self, view, width):
    ref=self.view_ref(view)
    total=len(view.lines); line=view.selected()
    suffix=None; show_percent=True
    if view.name=='finder':
        # finder has its own lines (files)
        suffix=f"file {view.lineno+1 if total else 0} of {total}"; show_percent=False
        left=f"[finder] {suffix}" if total else "[finder]"
        return left[:width]
    if view.name=='main':
        if total: suffix=f"commit {view.lineno+1} of {total}"
    elif view.name=='reflog':
        if total: suffix=f"reference {view.lineno+1} of {total}"
    elif view.name=='stash':
        if total: suffix=f"stash {view.lineno+1} of {total}"
    elif view.name=='tree':
        if line is not None and line.data.get('position_label'):
            suffix=line.data['position_label']
    elif view.name in ('refs','status'):
        suffix=None
    else:
        if total: suffix=f"line {view.lineno+1} of {total}"
    if ref and suffix: left=f"[{view.name}] {ref} - {suffix}"
    elif ref: left=f"[{view.name}] {ref}"
    elif suffix: left=f"[{view.name}] - {suffix}"
    else: left=f"[{view.name}]"
    # percent
    if not total: pct=0
    elif view.height<=0: pct=0
    elif total<=view.height: pct=100
    else:
        pct=int(100*(view.offset+view.height)/total)
        if pct>100: pct=100
    pctstr=f"{pct}%"
    if width<=len(pctstr):
        return pctstr[:width]
    if len(left)+1+len(pctstr)>width:
        left=left[:max(0,width-len(pctstr)-1)]
    return left + ' '*(width-len(left)-len(pctstr)) + pctstr

App.layout=_app_layout
App.view_ref=_app_view_ref
App.title_text=_app_title_text

# ---------- App: save-view / save-display data ----------
def _app_save_view_text(self, view):
    out=[]
    out.append(f"View: {view.name}")
    if view.prev: out.append(f"Prev: {view.prev}")
    if view.parent: out.append(f"Parent: {view.parent}")
    out.append(f"Ref: {self.view_ref(view)}")
    out.append(f"Dimensions: height={view.height} width={view.width}")
    out.append(f"Position: offset={view.offset} column={view.col_offset} lineno={view.lineno}")
    text_views={'diff','log','pager','blob','stage'}
    for i,ln in enumerate(view.lines):
        out.append(f"line[{i:3d}] type={ln.type} selected={1 if i==view.lineno else 0}")
        if view.name in text_views and ln.cells is not None:
            segtxt=''.join(f"[{t}]" for t,s in ln.cells)
            out.append(f"line[{i:3d}] cells={len(ln.cells)} text={segtxt}")
    return "\n".join(out)+"\n"

App.save_view_text=_app_save_view_text

