# ---------- App: layout / titles ----------
def _app_layout(self):
    W=self.screen_w; H=self.screen_h
    avail_h=max(1,H-1)
    layouts=[]
    disp=self.display
    if len(disp)<=1:
        if disp:
            v=disp[0]; v.width=W; v.height=max(0,avail_h-1)
            layouts.append({'view':v,'x':0,'y':0,'w':W,'h':v.height,'title_y':avail_h-1,'title_x':0,'title_w':W})
        return layouts
    # two views: parent first, child second
    parent,child=disp[0],disp[1]
    vs=str(self.cfg.options.get('vertical-split','auto'))
    vertical=False
    if vs=='vertical': vertical=True
    elif vs=='horizontal': vertical=False
    else: vertical = W >= 4*avail_h
    if vertical:
        usable=max(0,W-1)
        spec=str(self.cfg.options.get('split-view-width','50%'))
        if spec.endswith('%'):
            try: pct=int(spec[:-1])
            except Exception: pct=50
            right_w=int(usable*pct/100)
        else:
            try: right_w=int(spec)
            except Exception: right_w=usable//2
        # ensure smaller at least 4 wide if possible
        if usable>=8:
            right_w=max(4,min(right_w,usable-4))
        left_w=usable-right_w
        h=max(0,avail_h-1)
        parent.width=left_w; parent.height=h; child.width=right_w; child.height=h
        layouts.append({'view':parent,'x':0,'y':0,'w':left_w,'h':h,'title_y':avail_h-1,'title_x':0,'title_w':left_w})
        layouts.append({'view':child,'x':left_w+1,'y':0,'w':right_w,'h':h,'title_y':avail_h-1,'title_x':left_w+1,'title_w':right_w,'sep_x':left_w})
    else:
        spec=str(self.cfg.options.get('split-view-height','67%'))
        if spec.endswith('%'):
            try: pct=int(spec[:-1])
            except Exception: pct=67
            child_total=int(avail_h*pct/100)
        else:
            try: child_total=int(spec)+1
            except Exception: child_total=avail_h*2//3
        if avail_h>=10:
            child_total=max(5,min(child_total,avail_h-5))
        parent_total=avail_h-child_total
        parent_h=max(0,parent_total-1); child_h=max(0,child_total-1)
        parent.width=W; parent.height=parent_h; child.width=W; child.height=child_h
        layouts.append({'view':parent,'x':0,'y':0,'w':W,'h':parent_h,'title_y':parent_h,'title_x':0,'title_w':W})
        layouts.append({'view':child,'x':0,'y':parent_total,'w':W,'h':child_h,'title_y':parent_total+child_h,'title_x':0,'title_w':W})
    return layouts

def _app_view_ref(self, view):
    if view.name=='finder': return ''
    line=view.selected()
    if line is not None:
        if 'view_ref' in line.data: return line.data['view_ref'] or ''
        ci=line.data.get('commitinfo')
        if ci is not None:
            return getattr(ci,'id','') or ''
        if view.name in ('diff','log','pager'):
            if view.name=='pager': return ''
            return line.data.get('commit') or view.state.get('fallback_ref','') or ''
        if view.name=='blame':
            return f"{line.data.get('commit','')}:{line.data.get('filename',view.state.get('file',''))}"
    # no selected line
    if view.name=='diff': return view.state.get('fallback_ref','') or ''
    if view.name=='blob': return view.state.get('file','') or ''
    if view.name=='stage': return view.state.get('fallback_ref','') or ''
    return view.state.get('fallback_ref','') or ''

def _app_title_text(self, view, width):
    ref=self.view_ref(view)
    total=len(view.lines); line=view.selected()
    suffix=None; show_percent=True
    if view.name=='finder':
        # finder has its own lines (files)
        suffix=f"file {view.lineno+1 if total else 0} of {total}"; show_percent=False
        left=f"[finder] {suffix}" if total else "[finder]"
        return left[:width]
    if view.name=='main':
        if total: suffix=f"commit {view.lineno+1} of {total}"
    elif view.name=='reflog':
        if total: suffix=f"reference {view.lineno+1} of {total}"
    elif view.name=='stash':
        if total: suffix=f"stash {view.lineno+1} of {total}"
    elif view.name=='tree':
        if line is not None and line.data.get('position_label'):
            suffix=line.data['position_label']
    elif view.name in ('refs','status'):
        suffix=None
    else:
        if total: suffix=f"line {view.lineno+1} of {total}"
    if ref and suffix: left=f"[{view.name}] {ref} - {suffix}"
    elif ref: left=f"[{view.name}] {ref}"
    elif suffix: left=f"[{view.name}] - {suffix}"
    else: left=f"[{view.name}]"
    # percent
    if not total: pct=0
    elif view.height<=0: pct=0
    elif total<=view.height: pct=100
    else:
        pct=int(100*(view.offset+view.height)/total)
        if pct>100: pct=100
    pctstr=f"{pct}%"
    if width<=len(pctstr):
        return pctstr[:width]
    if len(left)+1+len(pctstr)>width:
        left=left[:max(0,width-len(pctstr)-1)]
    return left + ' '*(width-len(left)-len(pctstr)) + pctstr

