def _format_file_size(size, display):
    if size is None: return ''
    if display=='units':
        units=['','K','M','G','T']
        val=float(size); ui=0
        while val>=1024 and ui<len(units)-1:
            val/=1024.0; ui+=1
        if ui==0: return str(size)
        return f"{val:.1f}{units[ui]}"
    return str(size)

STATUS_LONG={'A':'added','M':'modified','D':'deleted','R':'renamed','C':'copied','T':'typechange','U':'unmerged','?':'untracked','!':'ignored','X':'unknown','B':'broken'}

def _app_line_number_value(self, view, line, idx):
    if view.name=='blame': return line.data.get('result_lineno', idx+1)
