def _app_column_hidden(self, view, col):
    disp=col.display()
    if disp=='no': return True
    if col.type=='file-name' and disp=='auto':
        if view.name=='blame':
            cur=view.state.get('file','')
            return not any((ln.data.get('filename') and ln.data.get('filename')!=cur) for ln in view.lines)
