def _app_compute_col_widths(self, view):
    cols=[c for c in self.view_columns(view.name) if not self._column_hidden(view,c)]
    widths={}
    # raw contents cache
    raw={}
    for ci,col in enumerate(cols):
        if col.type in ('commit-title','text'): 
            widths[ci]=None; continue
        if col.type=='file-name' and ci==len(cols)-1 and not col.opts.get('width') and not col.opts.get('maxwidth'):
            widths[ci]=None; continue
        explicit=col.opts.get('width')
        if explicit:
            try: widths[ci]=int(explicit)
            except Exception: widths[ci]=0
            continue
        # id width special
        if col.type=='id':
            widths[ci]=self.id_width(col); continue
        maxw=0
        for idx,ln in enumerate(view.lines):
            if ln.data.get('text_override') is not None: continue
            cells,align,flex=self._column_raw(view,ln,col,idx)
            maxw=max(maxw,cells_width(cells))
        if col.type=='line-number':
            # based on max value digits, minimum 3
            vals=[self._line_number_value(view,ln,i) for i,ln in enumerate(view.lines)]
            vals=[v for v in vals if v is not None]
            maxw=max(3, max((len(str(v)) for v in vals),default=0))
