    if ic=='yes' or (ic=='smart-case' and self.search_pattern.lower()==self.search_pattern):
        flags=re.IGNORECASE
    return re.compile(self.search_pattern,flags)

def _app_save_display_text(self):
    vrows=self._render_virtual()
    out=[]
    for row in vrows[:-1]:  # exclude status
        s=[]
        for c,res in row:
            if c is None: continue
            s.append(self._glyph_display_char(c,for_save=True) if is_glyph(c) else c)
        txt=''.join(s).rstrip(' ')
        out.append(txt if txt else ' ')
    return '\n'.join(out)+'\n'

App.graphics_mode=_app_graphics_mode
App._style_entry=_app_style_entry
App._resolve_style=_app_resolve_style
App._glyph_display_char=_app_glyph_display_char
App._render_virtual=_app_render_virtual
App._status_line_text=_app_status_line_text
App._apply_search_highlight=_app_apply_search_highlight
App._compiled_search=_app_compiled_search
App.save_display_text=_app_save_display_text

