def _app_load_blame(self, view):
    filepath=view.state.get('file','')
    rev=view.state.get('rev')  # could be None/''/commit
    wrev=rev if rev else 'HEAD'
    # ls-tree dir check (only on fresh blame from CLI / file changes; original seems to do it when opening blame view)
    rc,out=self.git.run(['git','ls-tree','-d','-z',wrev,filepath])
    if out and out.strip():
        view.state['load_error']=f"Cannot blame {filepath}"
        view.lines=[]; return
    blame_args=[]
    if getattr(self,'cli_blame_args',None) and view.state.get('from_cli'):
        blame_args=list(self.cli_blame_args)
    elif str(self.cfg.options.get('blame-options','')).strip():
        blame_args=_split_opts(self.cfg.options.get('blame-options',''))
    cmd=['git','blame','--encoding=UTF-8']+blame_args+['-p']
    if rev: cmd.append(rev)
    cmd.append('--'); cmd.append(filepath)
    rc,out=self.git.run(cmd)
    text=decode(out)
    lines=[]; commits={}
    cur=None
    # porcelain groups: parse iterator
    rawlines=text.splitlines(); i=0
    while i<len(rawlines):
        line=rawlines[i]; i+=1
        m=re.match(r'^([0-9a-f]{40}) (\d+) (\d+) (\d+)$',line)
        if not m: continue
        sha,orig,res,nlines=m.group(1),int(m.group(2)),int(m.group(3)),int(m.group(4))
        info=commits.get(sha)
        filename=filepath; previous=None; prev_file=None
        # header fields until content tab
        fields={}
        while i<len(rawlines) and not rawlines[i].startswith('\t'):
            kv=rawlines[i]; i+=1
            if ' ' in kv:
                k,v=kv.split(' ',1); fields[k]=v
            else: fields[kv]=''
        content=''
        if i<len(rawlines) and rawlines[i].startswith('\t'):
            content=rawlines[i][1:]; i+=1
        if info is None:
            info=CommitInfo(id=sha)
            commits[sha]=info
        if 'author' in fields:
            info.author_name=fields.get('author','')
            mail=fields.get('author-mail','').strip('<>')
            info.author_email=mail
            try: ats=int(fields.get('author-time','0'))
            except Exception: ats=0
            info.author_date=DateInfo(ats,fields.get('author-tz','+0000'))
        if 'committer' in fields:
            info.committer_name=fields.get('committer','')
            info.committer_email=fields.get('committer-mail','').strip('<>')
            try: cts=int(fields.get('committer-time','0'))
            except Exception: cts=0
            info.committer_date=DateInfo(cts,fields.get('committer-tz','+0000'))
        if 'summary' in fields: info.title=fields.get('summary','')
        if 'filename' in fields: filename=fields['filename']
        if 'previous' in fields:
            pv=fields['previous'].split(' ',1); previous=pv[0]; prev_file=pv[1] if len(pv)>1 else filename
            if previous and previous not in info.parents: info.parents=[previous]
        ln=Line('default',content,data={'commitinfo':info,'commit':sha,'id':sha,'filename':filename,'file':filename,'result_lineno':res,'orig_lineno':orig,'lineno':res,'text_content':content,'previous':previous,'previous_file':prev_file,'restore_key':res})
        lines.append(ln)
    view.lines=lines

def _app_load_grep(self, view):
    args=list(view.state.get('grep_args',[]))
    cmd=['git','grep','--no-color','-n','-z','--full-name']+args
    rc,out=self.git.run(cmd)
    # parse records: lines are file\0num\0text\n but text may contain \n? grep lines don't
    matches=[]
    for raw in decode(out).splitlines():
        parts=raw.split('\x00')
        if len(parts)>=3:
            fn,lnum=parts[0],parts[1]; txt='\x00'.join(parts[2:])
            try: n=int(lnum)
            except Exception:
                # -p function context format may give file\0func\0? fallback
                n=0; txt=raw
            matches.append((fn,n,txt))
        elif raw:
            # fallback parse file:num:text
            m=re.match(r'^([^:]+):(\d+):(.*)$',raw)
            if m: matches.append((m.group(1),int(m.group(2)),m.group(3)))
    view.state['matches']=matches
    self._build_grep_lines(view)

def _app_build_grep_lines(self, view):
    matches=view.state.get('matches',[])
    filecol=self.column_for('grep','file-name')
    show_file_column = filecol is not None and filecol.display()!='no'
    lines=[]
    if show_file_column:
        for fn,n,txt in matches:
            lines.append(Line('default',txt,data={'file_name':fn,'filename':fn,'file':fn,'file_lineno':n,'text_content':txt,'view_ref':fn,'restore_key':f'{fn}:{n}'}))
    else:
        last=None
        for fn,n,txt in matches:
            if fn!=last:
                lines.append(Line('file',fn,data={'text_override':fn,'override_style':'grep.file','filename':fn,'file':fn,'view_ref':fn,'restore_key':'file:'+fn}))
                last=fn
            lines.append(Line('default',txt,data={'filename':fn,'file':fn,'file_lineno':n,'text_content':txt,'view_ref':fn,'restore_key':f'{fn}:{n}'}))
    view.lines=lines

def _app_load_pager(self, view):
    if 'lines' in view.state and view.state.get('_pager_loaded'):
        # keep existing
        return
    data=view.state.get('pager_data')
    if data is None and self.stdin_mode=='pager' and self.initial_view=='pager':
        data=self.stdin_data
    if data is None:
        view.lines=[]; return
    parser=TextParser(self.cfg,'pager',insert_refs=False,repo=self.repo)
    lines=[]
    for raw in decode(data).splitlines(): lines.extend(parser.feed(raw))
    view.lines=lines; view.state['_pager_loaded']=True

def _app_load_finder(self, view):
    commit=view.state.get('commit') or self.repo.head_id or 'HEAD'
    rc,out=self.git.run(['git','ls-tree','-z','-r','--name-only','--full-name',commit])
    files=[p for p in decode(out).split('\x00') if p]
    self.finder_all_files=files
    view.state['all_files']=files
    self._build_finder_lines(view)

def _app_build_finder_lines(self,view):
    filt=view.state.get('filter','')
    files=view.state.get('all_files',[])
    if filt:
        selected=[f for f in files if filt.lower() in f.lower()]
    else: selected=files
    view.lines=[Line('file',f,data={'filename':f,'file':f,'view_ref':'','restore_key':f}) for f in selected]
    if view.lineno>=len(view.lines): view.lineno=max(0,len(view.lines)-1)

def _app_load_help(self, view):
    # expanded state preserved
    expanded=view.state.get('expanded')
    if expanded is None:
        expanded={'generic','search','toggle'}
        cur=view.state.get('opened_from')
        if cur and cur in KEYMAPS: expanded.add(cur)
        if cur is None: expanded.add('main')
        view.state['expanded']=expanded
    lines=[]
    def seg_line(typ,segments,data=None):
        ln=Line(typ,'',data=data or {}); ln.data['segments']=segments; return ln
    lines.append(seg_line('header',[('Quick reference for tig keybindings:','header')]))
    any_exp=bool(expanded)
    lines.append(seg_line('section',[(('[-] Collapse all sections' if any_exp else '[+] Expand all sections'),'section')],{'help_toggle_all':True}))
    lines.append(seg_line('default',[('','default')]))
    keymap_order=['generic','search','main','diff','reflog','refs','status','stage','stash','pager']
    for keymap in keymap_order:
        binds=[b for b in self.cfg.bindings if b.keymap==keymap]
        if not binds: continue
        is_exp=keymap in expanded
        marker='[-]' if is_exp else '[+]'
        lines.append(seg_line('section',[(f"{marker} {keymap} bindings",'section')],{'help_section':keymap}))
        if not is_exp: continue
        # group by binding group preserving order,within group by action preserving order
        groups=[]
        for b in binds:
            if b.group not in groups: groups.append(b.group)
        for grp in groups:
            lines.append(seg_line('help-group',[(grp,'help-group')]))
            # actions in group order
            acts=[]
            for b in binds:
                if b.group==grp and b.action not in acts: acts.append(b.action)
            for act in acts:
                keys=[b.token for b in binds if b.group==grp and b.action==act]
                keynames=[]
                for tok in keys:
                    nm=token_help_name(tok)
                    if nm==',': nm="','"
                    keynames.append(nm)
                keystr=', '.join(keynames)
                if act in ACTION_INFO:
                    desc=ACTION_INFO[act][1]
                    seg=[(f"{keystr:>28} ",'default'),(f"{act:<27}",'help-action'),(desc,'default')]
                else:
                    seg=[(f"{keystr:>28} ",'default'),(act,'help-action')]
                lines.append(seg_line('default',seg,{'help_action':act}))
    # toggle section
    is_exp='toggle' in expanded
    marker='[-]' if is_exp else '[+]'
    lines.append(seg_line('section',[(f"{marker} toggle bindings",'section')],{'help_section':'toggle'}))
    if is_exp:
        lines.append(seg_line('help-group',[('Toggle keys (enter: o <key>):','help-group')]))
        for key,name,desc in TOGGLES:
            seg=[(f"{key:>28} ",'default'),(f"{name:<27}",'help-action'),(desc,'default')]
            # in original format action field for long names may exceed; f-string padding min width handles
            lines.append(seg_line('help-toggle',seg,{'help_toggle':name}))
    view.lines=lines

App.load_refs=_app_load_refs
App.load_tree=_app_load_tree
App._read_local_file_lines=_read_local_file_lines
App.load_blob=_app_load_blob
App.load_status=_app_load_status
App.load_stage=_app_load_stage
App.load_blame=_app_load_blame
App.load_grep=_app_load_grep
App._build_grep_lines=_app_build_grep_lines
App.load_pager=_app_load_pager
App.load_finder=_app_load_finder
App._build_finder_lines=_app_build_finder_lines
App.load_help=_app_load_help

# load dispatcher
def _app_load_view(self, view, preserve=True):
    # preserve selected restore key / line index
    old_key=None; old_lineno=view.lineno; had_loaded=view.loaded
