        parts=raw.split('\x00')
        if len(parts)>=3:
            fn,lnum=parts[0],parts[1]; txt='\x00'.join(parts[2:])
            try: n=int(lnum)
            except Exception:
                # -p function context format may give file\0func\0? fallback
