def _app_build_grep_lines(self, view):
    matches=view.state.get('matches',[])
    filecol=self.column_for('grep','file-name')
    show_file_column = filecol is not None and filecol.display()!='no'
    lines=[]
    if show_file_column:
        for fn,n,txt in matches:
            lines.append(Line('default',txt,data={'file_name':fn,'filename':fn,'file':fn,'file_lineno':n,'text_content':txt,'view_ref':fn,'restore_key':f'{fn}:{n}'}))
    else:
        last=None
        for fn,n,txt in matches:
            if fn!=last:
                lines.append(Line('file',fn,data={'text_override':fn,'override_style':'grep.file','filename':fn,'file':fn,'view_ref':fn,'restore_key':'file:'+fn}))
                last=fn
            lines.append(Line('default',txt,data={'filename':fn,'file':fn,'file_lineno':n,'text_content':txt,'view_ref':fn,'restore_key':f'{fn}:{n}'}))
    view.lines=lines

