        view.state['expanded']=expanded
    lines=[]
    def seg_line(typ,segments,data=None):
        ln=Line(typ,'',data=data or {}); ln.data['segments']=segments; return ln
    lines.append(seg_line('header',[('Quick reference for tig keybindings:','header')]))
