            lines.append(seg_line('help-group',[(grp,'help-group')]))
            # actions in group order
            acts=[]
            for b in binds:
                if b.group==grp and b.action not in acts: acts.append(b.action)
            for act in acts:
                keys=[b.token for b in binds if b.group==grp and b.action==act]
                keynames=[]
                for tok in keys:
                    nm=token_help_name(tok)
                    if nm==',': nm="','"
                    keynames.append(nm)
                keystr=', '.join(keynames)
                if act in ACTION_INFO:
                    desc=ACTION_INFO[act][1]
                    seg=[(f"{keystr:>28} ",'default'),(f"{act:<27}",'help-action'),(desc,'default')]
                else:
                    seg=[(f"{keystr:>28} ",'default'),(act,'help-action')]
                lines.append(seg_line('default',seg,{'help_action':act}))
    # toggle section
    is_exp='toggle' in expanded
    marker='[-]' if is_exp else '[+]'
    lines.append(seg_line('section',[(f"{marker} toggle bindings",'section')],{'help_section':'toggle'}))
