        for key,name,desc in TOGGLES:
            seg=[(f"{key:>28} ",'default'),(f"{name:<27}",'help-action'),(desc,'default')]
            # in original format action field for long names may exceed; f-string padding min width handles
            lines.append(seg_line('help-toggle',seg,{'help_toggle':name}))
    view.lines=lines

