# ---------- App: opening views ----------
def _app_open_view(self, name, split=False, force_load=False, prev=None):
    view=self.views[name]
    old=self.current_view
    if split:
        if old is not None and view is not old:
            if view in self.display:
                self.focus=self.display.index(view)
            else:
                self.display=[old,view]
                view.parent=old.name; view.prev=old.name
                self.focus=1 if self.cfg.get_bool('focus-child') else 0
        elif not self.display:
            self.display=[view]; self.focus=0
    else:
        if view in self.display and len(self.display)>1:
            # maximise existing displayed view
            if old is not view: view.prev=old.name if old else view.prev
            self.display=[view]; view.parent=None; self.focus=0
        elif view is old and len(self.display)==1:
            pass
        else:
            if old is not None and view is not old: view.prev=old.name
            view.parent=None; self.display=[view]; self.focus=0
    # layout before load so view dimensions/stat width are known
    self.layout()
    if force_load or not view.loaded:
        self.load_view(view)
    else:
        view.clamp()
    return view

def _app_close_view(self, no_quit=False):
    if len(self.display)>1:
        cur=self.current_view
        # remove focused; focus remaining
        self.display=[v for v in self.display if v is not cur]
        self.focus=0
        if cur: cur.parent=None
        self.layout(); return
    cur=self.current_view
    if cur and cur.prev and cur.prev in self.views and self.views[cur.prev].loaded:
        prev_view=self.views[cur.prev]
        # Closing a view that was opened by switching returns to previous.
        # But initial view may have prev from a former switch cycle; tig view stack roughly mirrors this.
        self.display=[prev_view]; self.focus=0; prev_view.parent=None
        self.layout(); return
    if not no_quit:
        self.quit=True

def _context_commit_and_file(self):
    view=self.current_view; line=view.selected() if view else None
    commit=None; file=None; file_old=None
    if line:
        ci=line.data.get('commitinfo')
        commit=(ci.id if ci and ci.id and ci.id!='0'*40 else line.data.get('commit') or line.data.get('id'))
        if line.data.get('pseudo'):
            commit=self.repo.head_id
        file=line.data.get('file') or line.data.get('filename') or line.data.get('fullpath')
        if view.name=='tree' and line.data.get('entry_type')=='tree': file=None
        file_old=line.data.get('file_old')
    if not commit or commit=='0'*40: commit=self.repo.head_id or 'HEAD'
    return commit,file,file_old

def _app_open_diff_for(self, split=False, commit=None, file=None, file_old=None):
    cur=self.current_view; line=cur.selected() if cur else None
    # pseudo / status categories redirect
    pseudo=line.data.get('pseudo') if line else None
    if cur and cur.name=='main' and pseudo:
        if pseudo=='stat-untracked':
            return self.open_view('status',split=split,force_load=True)
        else:
            sv=self.views['stage']; sv.state['category']='staged' if pseudo=='stat-staged' else 'unstaged'; sv.state['file']=None; sv.state['file_old']=None
            return self.open_view('stage',split=split,force_load=True)
    if commit is None:
        commit,file2,file_old2=self._context_commit_and_file()
        if file is None: file=file2
        if file_old is None: file_old=file_old2
    dv=self.views['diff']
    changed = dv.state.get('mode')!='commit' or dv.state.get('commit')!=commit or dv.state.get('file')!=file
    dv.state['mode']='commit'; dv.state['commit']=commit; dv.state['file']=file; dv.state['file_old']=file_old; dv.state['fallback_ref']=commit
    return self.open_view('diff',split=split,force_load=changed or not dv.loaded)

def _app_open_stage_for(self, split=False, category=None, file=None, file_old=None, entry=None):
    # Determine from current line if not given
    cur=self.current_view; line=cur.selected() if cur else None
    if category is None:
        if line and line.data.get('pseudo')=='stat-staged': category='staged'
        elif line and line.data.get('pseudo')=='stat-unstaged': category='unstaged'
        elif line and line.data.get('status_section'): category=line.data['status_section']
        else:
            self.set_status('')
            return None
