# ---------- App: sorting / toggling ----------
def _next_cycle(cur, values):
    try: i=values.index(cur)
    except Exception: return values[0]
    return values[(i+1)%len(values)]

def _app_sort_lines(self, view):
    if not view.lines: return
    field=view.state.get('sort_field')
    if not field: return
    order=view.state.get('sort_order','ascending')
    sel=view.selected()
    def keyfn(pair):
        orig,ln=pair
        ci=ln.data.get('commitinfo')
        if field=='line-number': return ln.data.get('_orig_index',orig)
        if field=='id': return ln.data.get('id') or (ci.id if ci else '')
        if field=='date':
            col=self.column_for(view.name,'date')
            dinfo=None
            if ci: dinfo=ci.author_date if col is not None and col.opts.get('use-author')=='yes' else (ci.committer_date if ci else None)
            return dinfo.ts if dinfo else 0
        if field in ('author','committer'):
            if ci: return (ci.author_name if field=='author' else ci.committer_name).lower()
            return ln.data.get(f'{field}_name','')
        if field=='ref':
            r=ln.data.get('ref_obj')
            if r is not None: return (REF_PRIORITY.get(r.type,99),r.name)
            return (99,ln.data.get('ref_name',''))
        if field=='commit-title': return (ln.data.get('title') or (ci.title if ci else '')).lower()
        if field=='file-name':
            # directories first for tree in ascending
            isdir=0 if ln.type=='directory' else 1
            return (isdir,(ln.data.get('file_name') or ln.data.get('filename') or '').lower())
        if field=='file-size': return ln.data.get('file_size') or -1
        if field=='mode': return ln.data.get('mode_str','')
        if field=='status': return ln.data.get('status_char','')
        if field=='text': return ln.plain_text().lower()
        return orig
    indexed=list(enumerate(view.lines))
    indexed.sort(key=keyfn, reverse=(order=='descending'))
    view.lines=[ln for _,ln in indexed]
    if sel is not None:
        for i,ln in enumerate(view.lines):
            if ln is sel: view.lineno=i; break
    view.clamp()

def _app_toggle(self, name, args=''):
    view=self.current_view
    if view is None: return
    name=name.lower(); args=(args or '').strip()
    # Special sort toggles
    if name=='sort-order':
        cur=view.state.get('sort_order','ascending')
        new='descending' if cur=='ascending' else 'ascending'
        view.state['sort_order']=new; self.set_status(f"set sort-order = {new}")
        self._sort_lines(view); return
    if name=='sort-field':
        cols=[c.type for c in self.view_columns(view.name)]
        if not cols:
            self.set_status(f"`:toggle {name}` not supported"); return
        cur=view.state.get('sort_field')
        if cur not in cols:
            # default fields
            cur='ref' if view.name=='refs' else ('file-name' if view.name=='tree' else cols[0])
        new=_next_cycle(cur,cols)
        view.state['sort_field']=new; self.set_status(f"set sort-field = {new}")
        self._sort_lines(view); return
    # global enum/bool options
    global_cycles={
        'line-graphics':['ascii','default','utf-8','auto'],
        'ignore-space':['no','all','some','at-eol'],
        'commit-order':['auto','default','topo','date','author-date','reverse'],
        'vertical-split':['auto','vertical','horizontal'],
        'ignore-case':['no','yes','smart-case'],
        'refresh-mode':['auto','manual','after-command','periodic'],
    }
    if name in global_cycles:
        if args:
            ok,err=self.cfg.set_option(name,args); new=self.cfg.options.get(name)
        else:
            cur=str(self.cfg.options.get(name,global_cycles[name][0]))
            new=_next_cycle(cur,global_cycles[name]); self.cfg.options[name]=new
        self.set_status(f":set {name} = {new}")
        if name in ('ignore-space',) and view.name in ('diff','stage'): self.load_view(view)
        if name=='commit-order' and view.name=='main': self.load_view(view)
        self.invalidate(); return
    if name in ('file-filter','rev-filter','show-changes','show-untracked','status-show-untracked-dirs','status-show-untracked-files','wrap-lines','wrap-search','mouse','word-diff','mailmap','diff-indicator','diff-noprefix','focus-child','send-child-enter','start-on-head','editor-line-number','pager-autoscroll','mouse-wheel-cursor'):
        if args:
            ok,err=self.cfg.set_option(name,args); new=self.cfg.options.get(name)
        else:
            new='no' if self.cfg.get_bool(name) else 'yes'; self.cfg.options[name]=new
        self.set_status(f":set {name} = {new}")
        if view.name=='main' and name in ('show-changes','show-untracked','rev-filter'): self.load_view(view)
        if view.name in ('diff','stage') and name in ('file-filter','word-diff','diff-indicator'): self.load_view(view)
        if view.name=='status' and name.startswith('status-'): self.load_view(view)
        self.invalidate(); return
    if name=='diff-context':
        cur=self.cfg.get_int('diff-context',3)
        if args in ('+1','1'): new=cur+1
        elif args in ('-1',): new=cur-1
        elif args:
            try:
                new=int(args)
                if args[0] in '+-': new=cur+new
            except Exception: new=cur
        else: new=cur+1
        new=max(0,min(1024,new)); self.cfg.options[name]=new
        self.set_status(f":set diff-context = {new}")
        if view.name in ('diff','stage'): self.load_view(view)
        return
    # Column-related parsing
    coltype=None; optname='display'
    # forms: date, author, id, line-number, file-name, file-size, committer
    # commit-title-graph/refs/overflow, date-display/author-display/... , text overflow named commit-title-overflow globally
    if name=='commit-title-overflow':
        # could apply to commit-title column if present else text column
        if self.column_for(view.name,'commit-title') is not None:
            coltype='commit-title'; optname='overflow'
        elif self.column_for(view.name,'text') is not None:
            coltype='text'; optname='commit-title-overflow'
        else:
            self.set_status(f"`:toggle {name}` not supported"); return
    elif '-' in name:
        # try longest column prefix
        found=False
        for ct in sorted(ALL_COLUMN_TYPES,key=len,reverse=True):
            if name==ct:
                coltype=ct; optname='display'; found=True; break
            if name.startswith(ct+'-'):
                coltype=ct; optname=name[len(ct)+1:]; found=True; break
        if not found:
            # try suffix column: author-display -> display opt for author, date-format handled prefix above
            for ct in sorted(ALL_COLUMN_TYPES,key=len,reverse=True):
                if name.endswith('-'+ct):
                    coltype=ct; optname=name[:-(len(ct)+1)]; found=True; break
        if not found:
            self.set_status(f"`:toggle {name}` not supported"); return
    else:
        if name in ALL_COLUMN_TYPES: coltype=name; optname='display'
        else:
            self.set_status(f"`:toggle {name}` not supported"); return
    col=self.column_for(view.name,coltype)
    if col is None:
        self.set_status(f"`:toggle {name}` not supported"); return
    kind=COLUMN_OPTION_KINDS.get(coltype,{}).get(optname)
    if kind is None:
        self.set_status(f"`:toggle {name}` not supported"); return
    cur=col.opts.get(optname, default_display(coltype) if optname=='display' else 'no')
    # explicit arg value
    if args:
        newv,err=normalize_column_option(coltype,optname,args)
        if err and newv is None:
            self.set_status(err); return
        new=newv
    else:
        # cycles
        if coltype in ('author','committer') and optname=='display':
            new=_next_cycle(cur,['no','full','abbreviated','email','email-user'])
        elif coltype=='date' and optname=='display':
            new=_next_cycle(cur,['default','relative','relative-compact','custom','no'])
        elif coltype=='commit-title' and optname=='graph':
            new=_next_cycle(cur,['no','v2','v1'])
        elif coltype=='file-name' and optname=='display':
            new=_next_cycle(cur,['no','auto','always'])
        elif coltype=='file-size' and optname=='display':
            new=_next_cycle(cur,['no','default','units'])
        elif coltype=='status' and optname=='display':
            new=_next_cycle(cur,['no','short','long'])
        elif optname in ('overflow','commit-title-overflow'):
            new='no' if cur not in (None,'no',0,'0') else 50
        elif kind=='bool':
            new='no' if cur=='yes' else 'yes'
        elif isinstance(kind,tuple):
            new=_next_cycle(cur,kind[1])
        elif kind=='int':
            try: new=int(cur)+1
            except Exception: new=1
        else:
            new='no' if cur=='yes' else 'yes'
    col.opts[optname]=new
    # status name formatting
    if optname=='display': disp_name=f"{view.name}-view-{coltype}-display"
    else: disp_name=f"{view.name}-view-{coltype}-{optname}"
    self.set_status(f":set {disp_name} = {new}")
    # reloads
    if view.name=='main' and coltype=='commit-title' and optname=='graph': self.load_view(view)
    elif view.name=='grep' and coltype=='file-name': self._build_grep_lines(view); view.clamp()
    self.invalidate(view)

App._sort_lines=_app_sort_lines
App.toggle_option=_app_toggle

