def _app_cancel_prompt(self):
    self.mode='normal'; self.prompt=None; self.set_status('')

def _app_submit_prompt(self):
    p=self.prompt; self.mode='normal'; self.prompt=None
    if not p: return
    val=p.get('input','')
    kind=p.get('kind')
    if kind=='command':
        if val: self.history.append(('command',val))
        self.set_status('')
        self.run_prompt_command(val)
    elif kind=='search':
        if val: self.history.append(('search',val))
        self._do_search(val,direction=p.get('direction',1),start_after=False)
    elif kind=='grep':
        args=_split_opts(val) if val.strip() else []
        gv=self.views['grep']; gv.state['grep_args']=args
