    elif kind=='value':
        cb=p.get('callback')
        if cb: cb(val)
    elif kind=='confirm':
        pass

def _app_prompt_feed(self, token):
    p=self.prompt
    if not p: self.mode='normal'; return
    kind=p.get('kind')
    if kind=='confirm':
        if token[0]=='char' and token[1] in ('y','Y'):
            cb=p.get('callback'); self.mode='normal'; self.prompt=None; self.set_status('')
            if cb: cb(True)
        elif token[0] in ('char','key','ctrl','esc'):
            self.mode='normal'; self.prompt=None; self.set_status('')
            cb=p.get('callback')
            if cb: cb(False)
        return
    # search keymap while searching
    if kind=='search':
        act=None
        for b in reversed(self.cfg.bindings):
            if b.keymap=='search' and b.token==token: act=b.action; break
        if act=='find-next':
            self._do_search(p.get('input',''),direction=1,start_after=True); return
        if act=='find-prev':
            self._do_search(p.get('input',''),direction=-1,start_after=True); return
        if act=='view-close':
            self._cancel_prompt(); return
    if token==key_token('Enter'):
        self._submit_prompt(); return
    if token==ctrl_token('C') or token==key_token('Escape'):
        self._cancel_prompt(); return
    if token==key_token('Backspace'):
        cur=p['cursor']
        if cur>0: p['input']=p['input'][:cur-1]+p['input'][cur:]; p['cursor']=cur-1
        return
    if token==key_token('Delete'):
        cur=p['cursor']; p['input']=p['input'][:cur]+p['input'][cur+1:]; return
    if token==key_token('Left'):
        p['cursor']=max(0,p['cursor']-1); return
    if token==key_token('Right'):
        p['cursor']=min(len(p['input']),p['cursor']+1); return
    if token==key_token('Home') or token==ctrl_token('A'):
        p['cursor']=0; return
    if token==key_token('End') or token==ctrl_token('E'):
        p['cursor']=len(p['input']); return
    if token==ctrl_token('U'):
        p['input']=p['input'][p['cursor']:]; p['cursor']=0; return
    if token==ctrl_token('K'):
        p['input']=p['input'][:p['cursor']]; return
    if token==ctrl_token('W'):
        cur=p['cursor']; s=p['input'][:cur]
        s2=re.sub(r'\S+\s*$','',s)
        p['input']=s2+p['input'][cur:]; p['cursor']=len(s2); return
    if token in (key_token('Up'),key_token('Down')):
        # history
        hist=[v for k,v in self.history if k==kind or (kind=='command' and k=='command')]
        if not hist: return
        idx=p.get('history_idx')
        if token==key_token('Up'):
            idx=len(hist)-1 if idx is None else max(0,idx-1)
        else:
            idx=None if idx is None or idx>=len(hist)-1 else idx+1
        p['history_idx']=idx
        p['input']=hist[idx] if idx is not None else ''
        p['cursor']=len(p['input']); return
    if token==key_token('Tab'):
        # basic completion for command prompt
        if kind=='command':
            self._complete_prompt()
        return
    if token[0]=='char':
        c=token[1]; cur=p['cursor']; p['input']=p['input'][:cur]+c+p['input'][cur:]; p['cursor']=cur+len(c); return
    if token[0]=='ctrl':
        # Ctrl-J is enter in some contexts; curses converts \n to Enter before here
        return
    # ignore other keys

def _app_complete_prompt(self):
    p=self.prompt; s=p.get('input','')
    # If first word incomplete: complete from actions/config/prompt cmds
    m=re.match(r'^(\S*)$',s)
    completions=[]
    if m:
        candidates=sorted(list(ACTION_INFO.keys())+['set','bind','color','source','toggle','goto','save-display','save-view','save-options','script','exec','echo','quit'])
        completions=[c for c in candidates if c.startswith(s)]
        if len(completions)==1:
            p['input']=completions[0]; p['cursor']=len(p['input'])
        elif len(completions)>1:
            # common prefix
            pref=os.path.commonprefix(completions)
            if len(pref)>len(s): p['input']=pref; p['cursor']=len(pref)
            else: self.set_status(' '.join(completions))
        return
    # file path completion for save-*/script/source last word
    parts=s.split()
    if parts and parts[0] in ('save-display','save-view','save-options','script','source'):
        frag=parts[-1] if len(parts)>1 else ''
        dirn=os.path.dirname(frag) or '.'
        base=os.path.basename(frag)
        try: names=[n for n in os.listdir(dirn) if n.startswith(base)]
        except Exception: names=[]
        if len(names)==1:
            nf=os.path.join(dirn,names[0]) if dirn!='.' else names[0]
            p['input']=s[:len(s)-len(frag)]+nf; p['cursor']=len(p['input'])

