    expanded=command
    if force_pager:
        # run captured into pager
        try: argv=shlex.split(expanded)
        except Exception: argv=[]
        if argv:
            p=subprocess.run(argv,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
            out=p.stdout or b''
        else:
            p=subprocess.run(expanded,shell=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT); out=p.stdout or b''
        pv=self.views['pager']; pv.state['pager_data']=out; pv.state['_pager_loaded']=False; pv.state['fallback_ref']=expanded; pv.loaded=False
        self.open_view('pager',split=False,force_load=True)
        if '<' in flags: self.quit=True
        return
    if '@' in flags:
        try: argv=shlex.split(expanded)
        except Exception: argv=[]
        try:
            if argv: subprocess.Popen(argv,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
            else: subprocess.Popen(expanded,shell=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
