# ---------- App: actions ----------
def _app_move(self, delta):
    v=self.current_view
    if not v or not v.lines: return
    v.lineno=max(0,min(v.lineno+delta,len(v.lines)-1)); v.clamp()
def _app_move_page(self, pages):
    v=self.current_view
    if not v or not v.lines: return
    delta=pages*(v.height or 1)
    v.lineno=max(0,min(v.lineno+delta,len(v.lines)-1))
    v.offset=max(0,min(v.offset+delta,max(0,len(v.lines)-(v.height or 1))))
    v.clamp()
def _app_move_half(self, halfs):
    v=self.current_view
    if not v or not v.lines: return
    delta=halfs*max(1,(v.height or 2)//2)
    v.lineno=max(0,min(v.lineno+delta,len(v.lines)-1)); v.clamp()
def _app_scroll(self, delta):
    v=self.current_view
    if not v or not v.lines: return
    maxoff=max(0,len(v.lines)-(v.height or 1))
    oldoff=v.offset
    v.offset=max(0,min(v.offset+delta,maxoff))
    real=v.offset-oldoff
    v.lineno=max(0,min(v.lineno+real,len(v.lines)-1)); v.clamp()
def _app_scroll_horiz(self, direction):
    v=self.current_view
    if not v: return
    spec=str(self.cfg.options.get('horizontal-scroll','50%'))
    if spec.endswith('%'):
        try: step=max(1,int((v.width or self.screen_w)*int(spec[:-1])/100))
        except Exception: step=max(1,(v.width or 80)//2)
    else:
        try: step=int(spec)
        except Exception: step=1
    v.col_offset=max(0,v.col_offset+direction*step)

def _app_execute_action(self, action):
    if action is None: return
    act=action.strip() if isinstance(action,str) else action
    if act=='none' or act=='': return
    if act.startswith(':'):
        self.run_prompt_command(act[1:]); return
    if act and act[0] in '!?@<+>' and act not in ACTION_INFO:
        self.run_external(act); return
    view=self.current_view
    # view switching
    if act.startswith('view-'):
        name=act[5:]
        self._switch_view(name); return
    if act=='enter':
        self._action_enter(); return
    if act=='back':
        self._action_back(); return
    if act in ('next',): self._move(1); return
    if act in ('previous',): self._move(-1); return
    if act=='parent':
        self._action_parent(); return
    if act=='view-next':
        if len(self.display)>1: self.focus=(self.focus+1)%len(self.display)
        return
    if act=='refresh':
        try: self.repo.load_refs()
        except Exception: pass
        for v in list(self.display): self.load_view(v)
        return
    if act=='maximize':
        if len(self.display)>1:
            cur=self.current_view; self.display=[cur]; cur.parent=None; self.focus=0; self.layout()
        return
    if act=='view-close':
        self.close_view(False); return
    if act=='view-close-no-quit':
        self.close_view(True); return
    if act=='quit':
        self.quit=True; return
    if act=='status-update':
        self.status_update(); return
    if act=='stage-update-line':
        self.stage_update_line(); return
    if act=='stage-update-part':
        self.stage_update_part(); return
    if act=='stage-split-chunk':
        self.stage_split_chunk(); return
    if act=='status-revert':
        self._status_revert(); return
    if act=='status-merge':
        f=self._current_file()
        if f: self.run_external(f"!git mergetool {shlex.quote(f)}")
        return
    if act=='move-up': self._move(-1); return
    if act=='move-down': self._move(1); return
    if act=='move-page-up': self._move_page(-1); return
    if act=='move-page-down': self._move_page(1); return
    if act=='move-half-page-up': self._move_half(-1); return
    if act=='move-half-page-down': self._move_half(1); return
    if act=='move-first-line':
        if view: view.lineno=0; view.clamp()
        return
    if act=='move-last-line':
        if view and view.lines: view.lineno=len(view.lines)-1; view.clamp()
        return
    if act in ('move-next-merge','move-prev-merge'):
        # find next/prev main-commit with >1 parents
        if view:
            step=1 if act=='move-next-merge' else -1
            i=view.lineno+step
            while 0<=i<len(view.lines):
                ci=view.lines[i].data.get('commitinfo')
                if ci and len(getattr(ci,'parents',[]))>1: view.lineno=i; view.clamp(); break
                i+=step
        return
    if act=='scroll-line-up': self._scroll(-1); return
    if act=='scroll-line-down': self._scroll(1); return
    if act=='scroll-page-up': self._scroll(-(view.height if view else 1)); return
    if act=='scroll-page-down': self._scroll((view.height if view else 1)); return
    if act=='scroll-half-page-up': self._scroll(-max(1,((view.height if view else 2)//2))); return
    if act=='scroll-half-page-down': self._scroll(max(1,((view.height if view else 2)//2))); return
    if act=='scroll-first-col':
        if view: view.col_offset=0
        return
    if act=='scroll-left': self._scroll_horiz(-1); return
    if act=='scroll-right': self._scroll_horiz(1); return
    if act=='search':
        self._start_prompt('search','/',direction=1); return
    if act=='search-back':
        self._start_prompt('search','?',direction=-1); return
    if act=='find-next': self._find_next(False); return
    if act=='find-prev': self._find_next(True); return
    if act=='edit':
        self.edit_file(); return
    if act=='prompt':
        self._start_prompt('command',':'); return
    if act=='options':
        self.mode='options'; self.options_index=0; self._update_options_status(); return
    if act=='screen-redraw':
        if self.curses_screen:
            try: self.curses_screen.clearok(True)
            except Exception: pass
        self.invalidate(); return
    if act=='stop-loading': return
    if act=='show-version':
        self.set_status(f"tig-{VERSION}"); return
    # unknown named action from prompt already handled

def _app_update_options_status(self):
    idx=self.options_index % len(TOGGLES)
    key,name,desc=TOGGLES[idx]
    short=desc[len('Toggle '):] if desc.startswith('Toggle ') else desc
    left=f"Toggle option {short} [{key}]"
    right=f"({idx+1} of {len(TOGGLES)})"
    w=self.screen_w
    self.status_message=left+' '*(max(1,w-len(left)-len(right)))+right

def _app_switch_view(self,name):
    cur=self.current_view
    if name=='main':
        self.open_view('main',split=False,force_load=False); return
    if name=='log':
        self.open_view('log',split=False,force_load=False); return
    if name=='reflog':
        self.open_view('reflog',split=False,force_load=False); return
    if name=='diff':
        self.open_diff_for(split=False); return
    if name=='tree':
        commit,file,_=self._context_commit_and_file()
        # if current line is pseudo, context commit returns HEAD but original did nothing for tree on pseudo; check
        line=cur.selected() if cur else None
        if line and line.data.get('pseudo'):
            return
        tv=self.views['tree']
        changed=tv.state.get('commit')!=commit
        tv.state['commit']=commit
        if changed:
            tv.state['path']=''; tv.state['_pos_init']=False; tv.state['history']=[]
        self.open_view('tree',split=False,force_load=changed or not tv.loaded); return
    if name=='blob':
        # if current file known, open blob; else finder
        commit,file,_=self._context_commit_and_file()
        line=cur.selected() if cur else None
        if file and line and not line.data.get('pseudo'):
            bv=self.views['blob']
            # determine blob id: tree line blob, or if status/stage/blame/grep a worktree file
            blobid=line.data.get('blob')
            if cur.name=='tree' and line.data.get('entry_type')=='blob': blobid=line.data.get('id')
            if blobid: bv.state['blob']=blobid
            else: bv.state['blob']=None
            bv.state['file']=file; bv.state['commit']=commit
            self.open_view('blob',split=False,force_load=True)
        else:
            fv=self.views['finder']; fv.state['commit']=commit; fv.state['filter']=''; fv.state['return_view']=cur.name if cur else 'main'; fv.lineno=0
            self.open_view('finder',split=False,force_load=True)
            self.mode='finder'
        return
    if name=='blame':
        commit,file,_=self._context_commit_and_file()
        line=cur.selected() if cur else None
        if not file or (line and line.data.get('pseudo')) or (cur and cur.name=='tree' and line and line.data.get('entry_type')=='tree'):
