# ---------- App: curses rendering / main loop ----------
def _app_curses_attr(self,res):
    import curses
    fg,bg,attrs=res
    fgn=_color_num(fg); bgn=_color_num(bg)
    key=(fgn,bgn)
    pair=self._pair_cache.get(key)
    if pair is None:
        self._next_pair+=0
        n=self._next_pair; self._next_pair+=1
        try:
            curses.init_pair(n,fgn,bgn); pair=n
        except Exception:
            pair=0
        self._pair_cache[key]=pair
    a=curses.color_pair(pair)
    for at in attrs:
        if at=='bold': a|=curses.A_BOLD
        elif at=='dim': a|=curses.A_DIM
        elif at=='underline': a|=curses.A_UNDERLINE
        elif at=='reverse': a|=curses.A_REVERSE
        elif at=='blink': a|=curses.A_BLINK
        elif at=='standout': a|=curses.A_STANDOUT
    return a

def _app_flush(self):
    import curses
    scr=self.curses_screen
    if scr is None: return
    try:
        h,w=scr.getmaxyx()
        if (w,h)!=(self.screen_w,self.screen_h):
            self.screen_w,self.screen_h=w,h
    except Exception: pass
    vrows=self._render_virtual()
    scr.erase()
    mode=self.graphics_mode()
    acsmap={
        'vline':curses.ACS_VLINE,'hline':curses.ACS_HLINE,'urcorner':curses.ACS_URCORNER,'ulcorner':curses.ACS_ULCORNER,
        'lrcorner':curses.ACS_LRCORNER,'llcorner':curses.ACS_LLCORNER,'ttee':curses.ACS_TTEE,'btee':curses.ACS_BTEE,
        'rtee':curses.ACS_RTEE,'ltee':curses.ACS_LTEE,'plus':curses.ACS_PLUS,
    }
    H=len(vrows); W=self.screen_w
    for y,row in enumerate(vrows):
        x=0
