    view=self.current_view; line=view.selected() if view else None
    if view is None or line is None:
        self.set_status('Nothing to edit'); return
    f=None; lineno=0; is_blob_temp=False
    if view.name=='tree':
        if line.data.get('entry_type')!='blob':
            self.set_status('Nothing to edit'); return
        f=line.data.get('fullpath'); lineno=0
    elif view.name=='status':
        if not line.data.get('entry'):
            self.set_status('Nothing to edit'); return
        f=line.data.get('file'); lineno=0
    elif view.name in ('diff','stage','pager'):
        f=line.data.get('file')
        if not f:
            self.set_status('Nothing to edit'); return
        try: lineno=int(line.data.get('lineno',0) or 0)
        except Exception: lineno=0
        if line.type in ('diff-stat','diff-start','diff-header','diff-chunk'): lineno=0
    elif view.name=='grep':
        f=line.data.get('file'); lineno=line.data.get('file_lineno',0)
        if not f:
            self.set_status('Nothing to edit'); return
    elif view.name=='blob':
        f=view.state.get('file')
        if not f:
            self.set_status('Nothing to edit'); return
        lineno=view.lineno+1
        if view.state.get('blob'):
            is_blob_temp=True
    else:
        self.set_status('Nothing to edit'); return
    editor=os.environ.get('TIG_EDITOR') or os.environ.get('GIT_EDITOR') or self.repo.config_get('core.editor') or os.environ.get('VISUAL') or os.environ.get('EDITOR') or 'vi'
    temp_path=None
    edit_path=f
    if is_blob_temp:
        import tempfile
        fd,temp_path=tempfile.mkstemp(prefix='tigblob.',suffix='.'+os.path.basename(f))
        with os.fdopen(fd,'w') as out:
            for ln in view.lines: out.write(ln.plain_text()+'\\n')
        edit_path=temp_path
    if self.cfg.get_bool('editor-line-number') and lineno>0:
        cmd=f"{editor} +{lineno} {shlex.quote(edit_path)}"
    else:
        cmd=f"{editor} {shlex.quote(edit_path)}"
    cmd=self._expand_state(cmd)
    self._run_foreground(None,shell_str=cmd)
    if temp_path:
        try: os.remove(temp_path)
        except Exception: pass
    for v in list(self.display):
        try: self.load_view(v)
        except Exception: pass

'''
s=s[:start]+replacement+s[end:]
p.write_text(s)
